import {chromium} from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
try {
  const context = await browser.newContext({locale: 'en-US'});
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto('http://localhost:5173');
  await page.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
  await page.getByRole('radio', {name: 'Русский', exact: true}).check();
  await page.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
  assert.equal(await page.locator('html').getAttribute('lang'), 'ru');
  assert.equal(await page.title(), 'Настройки языка · Рабочее пространство');
  assert.equal(await page.evaluate(() => localStorage.getItem('app.language')), 'ru');
  await page.reload();
  await page.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
  assert.equal(await page.getByRole('radio', {name: 'Русский', exact: true}).isChecked(), true);
  await page.getByRole('radio', {name: 'Русский', exact: true}).focus();
  await page.keyboard.press('ArrowLeft');
  await page.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
  await page.reload();
  await page.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
  await page.setViewportSize({width: 375, height: 812});
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth), true);
  await page.screenshot({path: '/tmp/language-ui-check/mobile.png'});
  const russian = await browser.newContext({locale: 'ru-RU'});
  const ruPage = await russian.newPage();
  await ruPage.goto('http://localhost:5173');
